local BookPressMaker = {}
local PRODUCTS = {
    iron_book_press = { name = "Železno stiskalo knjig", ironCost = 4, woodCost = 3, leatherCost = 1, time = 6, cost = 190, prestige = 4, happiness = 2, description = "Železno stiskalo za vezavo knjig." },
    bronze_book_press = { name = "Bronasto stiskalo knjig", bronzeCost = 4, ironCost = 1, woodCost = 3, leatherCost = 1, time = 8, cost = 460, prestige = 6, happiness = 3, description = "Bronasto stiskalo za trdno vezavo." },
    silver_book_press = { name = "Srebrno stiskalo knjig", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 12, cost = 1110, prestige = 11, happiness = 4, description = "Srebrno stiskalo za plemiške knjigoveže." },
    gilded_book_press = { name = "Pozlačeno stiskalo knjig", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 16, cost = 2380, prestige = 20, happiness = 5, description = "Pozlačeno stiskalo za dvorne knjigoveže." },
    jewel_set_book_press = { name = "Draguljasto stiskalo knjig", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 20, cost = 5100, prestige = 36, happiness = 7, description = "Draguljasto stiskalo za kraljevske knjigoveže." },
    royal_sovereign_book_press = { name = "Kraljevski suvereno stiskalo knjig", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 27, cost = 10900, prestige = 69, happiness = 13, description = "Suvereno stiskalo z biseri za krono." },
}
local BUILDINGS = {
    bookpress_workshop = { name = "Stiskarska delavnica", cost = { gold = 380, wood = 185, stone = 150, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    bookpress_house = { name = "Stiskarska hiša", cost = { gold = 1310, wood = 370, stone = 295, silver = 8, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    master_bookpress_atelier = { name = "Mojstrski stiskarski atelje", cost = { gold = 3230, wood = 430, stone = 550, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_bookpress_palace = { name = "Suverena stiskarska palača", cost = { gold = 13800, wood = 660, stone = 870, gold = 89, jewel = 20 }, upkeep = 264, qualityBonus = 55, prestigeBonus = 50 },
}
BookPressMaker.ironStock = 16; BookPressMaker.bronzeStock = 14; BookPressMaker.woodStock = 14; BookPressMaker.leatherStock = 10; BookPressMaker.silverStock = 8; BookPressMaker.goldStock = 6; BookPressMaker.jewelStock = 4; BookPressMaker.pearlStock = 4
BookPressMaker.productStock = {}; BookPressMaker.buildings = {}; BookPressMaker.maker = nil; BookPressMaker.activeMaking = {}; BookPressMaker.totalProducts = 0; BookPressMaker.dayTimer = 0
function BookPressMaker.init() BookPressMaker.ironStock=16; BookPressMaker.bronzeStock=14; BookPressMaker.woodStock=14; BookPressMaker.leatherStock=10; BookPressMaker.silverStock=8; BookPressMaker.goldStock=6; BookPressMaker.jewelStock=4; BookPressMaker.pearlStock=4; BookPressMaker.productStock={}; BookPressMaker.buildings={}; BookPressMaker.maker=nil; BookPressMaker.activeMaking={}; BookPressMaker.totalProducts=0; BookPressMaker.dayTimer=0; print("[BookPressMaker] Royal Book Press Maker System initialized (6 products, 4 buildings)") end
function BookPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookPressMaker.maker={name=n or ("Stiskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskar najet: %s (spretnost: %d)",BookPressMaker.maker.name,s),"success") end; return true end
function BookPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookPressMaker.build(id) local ok,e=BookPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookPressMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookPressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookPressMaker.buildings==0 then return false,"Potrebna stiskarska delavnica" end; if not BookPressMaker.maker then return false,"Potreben stiskar" end; return true end
function BookPressMaker.make(pt,qty) qty=qty or 1; local ok,e=BookPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookPressMaker.ironStock=BookPressMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookPressMaker.bronzeStock=BookPressMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookPressMaker.woodStock=BookPressMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookPressMaker.leatherStock=BookPressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookPressMaker.silverStock=BookPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookPressMaker.goldStock=BookPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookPressMaker.jewelStock=BookPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookPressMaker.pearlStock=BookPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookPressMaker.maker then t=math.max(1,t-math.floor(BookPressMaker.maker.skill/13)) end; table.insert(BookPressMaker.activeMaking,{id="bookpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookPressMaker.completeMaking(m) local q=1.0+(BookPressMaker.getQualityBonus()/100); if BookPressMaker.maker then q=q+(BookPressMaker.maker.skill/140) end; q=math.min(2.5,q); BookPressMaker.productStock[m.productType]=(BookPressMaker.productStock[m.productType] or 0)+m.quantity; BookPressMaker.totalProducts=BookPressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookPressMaker.maker then BookPressMaker.maker.itemsMade=BookPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookPressMaker.maker.skill=math.min(100,BookPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookpress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookPressMaker.update(dt) if not _G.state then return end; BookPressMaker.dayTimer=BookPressMaker.dayTimer+dt; if BookPressMaker.dayTimer>=30 then BookPressMaker.dayTimer=0; for i=#BookPressMaker.activeMaking,1,-1 do local m=BookPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookPressMaker.completeMaking(m); table.remove(BookPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookPressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookPressMaker.getStats() return {ironStock=BookPressMaker.ironStock,bronzeStock=BookPressMaker.bronzeStock,woodStock=BookPressMaker.woodStock,leatherStock=BookPressMaker.leatherStock,silverStock=BookPressMaker.silverStock,goldStock=BookPressMaker.goldStock,jewelStock=BookPressMaker.jewelStock,pearlStock=BookPressMaker.pearlStock,productStock=BookPressMaker.productStock,numBuildings=#BookPressMaker.buildings,hasMaker=BookPressMaker.maker~=nil,makerName=BookPressMaker.maker and BookPressMaker.maker.name or "—",makerSkill=BookPressMaker.maker and BookPressMaker.maker.skill or 0,activeMaking=#BookPressMaker.activeMaking,totalProducts=BookPressMaker.totalProducts} end
return BookPressMaker
